local YogurtFermenter = {}
local PRODUCTS = {
    plain_yogurt = { name = "Navaden jogurt", milkCost = 2, cultureCost = 1, time = 2, cost = 12, flavorStrength = 25, happiness = 1, description = "Navaden jogurt za vsakdanjo rabo." },
    honey_yogurt = { name = "Medeni jogurt", milkCost = 3, cultureCost = 1, honeyCost = 1, time = 3, cost = 30, flavorStrength = 40, happiness = 2, prestige = 1, description = "Medeni jogurt z dodatkom medu." },
    fruit_yogurt = { name = "Sadni jogurt", milkCost = 3, cultureCost = 1, fruitCost = 1, honeyCost = 1, time = 4, cost = 65, flavorStrength = 55, happiness = 3, prestige = 2, description = "Sadni jogurt z gozdnim sadjem." },
    spiced_yogurt = { name = "Začinjen jogurt", milkCost = 4, cultureCost = 1, spiceCost = 1, honeyCost = 1, time = 6, cost = 150, flavorStrength = 70, happiness = 4, prestige = 5, description = "Začinjen jogurt z žafranom." },
    silver_vessel_yogurt = { name = "Srebrno posodje jogurt", milkCost = 5, cultureCost = 1, silverCost = 1, honeyCost = 1, fruitCost = 1, time = 9, cost = 380, flavorStrength = 85, happiness = 6, prestige = 11, description = "Jogurt iz srebrnega posodja za plemiče." },
    royal_grand_yogurt = { name = "Kraljevski veliki jogurt", milkCost = 10, cultureCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, honeyCost = 2, fruitCost = 2, time = 14, cost = 1200, flavorStrength = 100, happiness = 13, prestige = 33, description = "Veliki kraljevski jogurt z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Jogurtarska delavnica", cost = { gold = 260, wood = 120, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    fermentation_room = { name = "Fermentirnica", cost = { gold = 850, wood = 220, stone = 350, milk = 10 }, upkeep = 20, qualityBonus = 18 },
    cooling_room = { name = "Hladilnica", cost = { gold = 2100, wood = 300, stone = 600, silver = 30, ice = 10 }, upkeep = 50, qualityBonus = 30 },
    royal_yogurt_atelier = { name = "Kraljevski atelje jogurta", cost = { gold = 8500, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 170, qualityBonus = 55, prestigeBonus = 40 },
}
YogurtFermenter.milkStock = 22; YogurtFermenter.cultureStock = 14; YogurtFermenter.honeyStock = 12; YogurtFermenter.fruitStock = 14; YogurtFermenter.spiceStock = 10; YogurtFermenter.silverStock = 8; YogurtFermenter.goldStock = 6; YogurtFermenter.jewelStock = 6
YogurtFermenter.productStock = {}; YogurtFermenter.buildings = {}; YogurtFermenter.maker = nil; YogurtFermenter.activeMaking = {}; YogurtFermenter.totalProducts = 0; YogurtFermenter.dayTimer = 0
function YogurtFermenter.init() YogurtFermenter.milkStock=22; YogurtFermenter.cultureStock=14; YogurtFermenter.honeyStock=12; YogurtFermenter.fruitStock=14; YogurtFermenter.spiceStock=10; YogurtFermenter.silverStock=8; YogurtFermenter.goldStock=6; YogurtFermenter.jewelStock=6; YogurtFermenter.productStock={}; YogurtFermenter.buildings={}; YogurtFermenter.maker=nil; YogurtFermenter.activeMaking={}; YogurtFermenter.totalProducts=0; YogurtFermenter.dayTimer=0; print("[YogurtFermenter] Royal Yogurt Fermenter System initialized (6 products, 4 buildings)") end
function YogurtFermenter.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; YogurtFermenter.maker={name=n or ("Jogurtar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Jogurtar najet: %s (spretnost: %d)",YogurtFermenter.maker.name,s),"success") end; return true end
function YogurtFermenter.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function YogurtFermenter.build(id) local ok,e=YogurtFermenter.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(YogurtFermenter.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function YogurtFermenter.getQualityBonus() local b=0; for _,bd in ipairs(YogurtFermenter.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function YogurtFermenter.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.milkCost and YogurtFermenter.milkStock<(d.milkCost or 0) then return false,"Premalo mleka" end; if d.cultureCost and YogurtFermenter.cultureStock<(d.cultureCost or 0) then return false,"Premalo kultur" end; if d.honeyCost and YogurtFermenter.honeyStock<(d.honeyCost or 0) then return false,"Premalo medu" end; if d.fruitCost and YogurtFermenter.fruitStock<(d.fruitCost or 0) then return false,"Premalo sadja" end; if d.spiceCost and YogurtFermenter.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.silverCost and YogurtFermenter.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and YogurtFermenter.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and YogurtFermenter.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #YogurtFermenter.buildings==0 then return false,"Potrebna delavnica" end; if not YogurtFermenter.maker then return false,"Potreben jogurtar" end; return true end
function YogurtFermenter.make(pt,qty) qty=qty or 5; local ok,e=YogurtFermenter.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.milkCost then YogurtFermenter.milkStock=YogurtFermenter.milkStock-d.milkCost*qty end; if d.cultureCost then YogurtFermenter.cultureStock=YogurtFermenter.cultureStock-d.cultureCost*qty end; if d.honeyCost then YogurtFermenter.honeyStock=YogurtFermenter.honeyStock-d.honeyCost*qty end; if d.fruitCost then YogurtFermenter.fruitStock=YogurtFermenter.fruitStock-d.fruitCost*qty end; if d.spiceCost then YogurtFermenter.spiceStock=YogurtFermenter.spiceStock-d.spiceCost*qty end; if d.silverCost then YogurtFermenter.silverStock=YogurtFermenter.silverStock-d.silverCost*qty end; if d.goldCost then YogurtFermenter.goldStock=YogurtFermenter.goldStock-d.goldCost*qty end; if d.jewelCost then YogurtFermenter.jewelStock=YogurtFermenter.jewelStock-d.jewelCost*qty end; local t=d.time; if YogurtFermenter.maker then t=math.max(1,t-math.floor(YogurtFermenter.maker.skill/12)) end; table.insert(YogurtFermenter.activeMaking,{id="yogurt_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,flavorStrength=d.flavorStrength or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function YogurtFermenter.completeMaking(m) local q=1.0+(YogurtFermenter.getQualityBonus()/100); if YogurtFermenter.maker then q=q+(YogurtFermenter.maker.skill/180) end; q=math.min(2.0,q); YogurtFermenter.productStock[m.productType]=(YogurtFermenter.productStock[m.productType] or 0)+m.quantity; YogurtFermenter.totalProducts=YogurtFermenter.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if YogurtFermenter.maker then YogurtFermenter.maker.itemsMade=YogurtFermenter.maker.itemsMade+m.quantity; if math.random()<0.20 then YogurtFermenter.maker.skill=math.min(100,YogurtFermenter.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Jogurt izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"yogurt.completed",{productName=m.productName,flavorStrength=m.flavorStrength,happiness=m.happiness}) end end
function YogurtFermenter.update(dt) if not _G.state then return end; YogurtFermenter.dayTimer=YogurtFermenter.dayTimer+dt; if YogurtFermenter.dayTimer>=30 then YogurtFermenter.dayTimer=0; for i=#YogurtFermenter.activeMaking,1,-1 do local m=YogurtFermenter.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then YogurtFermenter.completeMaking(m); table.remove(YogurtFermenter.activeMaking,i) end end; local tu=0; for _,bd in ipairs(YogurtFermenter.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if YogurtFermenter.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function YogurtFermenter.getStats() return {milkStock=YogurtFermenter.milkStock,cultureStock=YogurtFermenter.cultureStock,honeyStock=YogurtFermenter.honeyStock,fruitStock=YogurtFermenter.fruitStock,spiceStock=YogurtFermenter.spiceStock,silverStock=YogurtFermenter.silverStock,goldStock=YogurtFermenter.goldStock,jewelStock=YogurtFermenter.jewelStock,productStock=YogurtFermenter.productStock,numBuildings=#YogurtFermenter.buildings,hasMaker=YogurtFermenter.maker~=nil,makerName=YogurtFermenter.maker and YogurtFermenter.maker.name or "—",makerSkill=YogurtFermenter.maker and YogurtFermenter.maker.skill or 0,activeMaking=#YogurtFermenter.activeMaking,totalProducts=YogurtFermenter.totalProducts} end
return YogurtFermenter
